SELECT is_flagged, merchant, CASE WHEN txn_type IN ('REFUND', 'DEBIT') THEN 'group_a' ELSE 'other' END txn_type_group, SUM(CASE WHEN txn_type = 'FEE' THEN 1 ELSE 0 END) fee_count, ROUND((100 * SUM(CASE WHEN merchant = 'Starbucks' THEN 1 ELSE 0 END)) / COUNT(*), 1) pct_starbucks, COUNT(*) cnt FROM transactions GROUP BY is_flagged, merchant, CASE WHEN txn_type IN ('REFUND', 'DEBIT') THEN 'group_a' ELSE 'other' END HAVING cnt > 2
